import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { getActiveCompanyCode, getAuthUser } from '@linm-soft-org/linm-web-common-components';
import { apiClient, unwrap, type BffResponse } from '../../../services/api';

const PKH_FORM_NAME = 'plan-voucher';

interface FormInitFieldDefaultsDto {
  fieldDefaults?: Record<string, string>;
}

/**
 * Default Chi nhánh phiếu KH = tập đoàn (FM), không phải cửa hàng đang active (FM01).
 * SSOT: VoucherRegistryFieldDefaults (branchCode / companyCode) via form init-data.
 */
export async function resolvePlanVoucherDefaultBranchCode(
  companies: ActiveCompanyItem[],
): Promise<{ code: string; company: ActiveCompanyItem | null }> {
  const byCode = (code: string) => {
    const u = code.trim().toUpperCase();
    if (!u) return null;
    return companies.find(c => (c.code ?? c.id).toUpperCase() === u) ?? null;
  };

  let preferred = '';
  try {
    const res = await apiClient.get<BffResponse<FormInitFieldDefaultsDto>>(
      `/forms/init-data?formName=${encodeURIComponent(PKH_FORM_NAME)}`,
    );
    const defaults = unwrap(res)?.fieldDefaults;
    preferred = (defaults?.branchCode || defaults?.companyCode || '').trim().toUpperCase();
  } catch {
    // init-data chưa sẵn / form chưa map — fallback bên dưới
  }

  if (!preferred) preferred = 'FM';

  const fromRegistry = byCode(preferred);
  if (fromRegistry) {
    return { code: fromRegistry.code ?? fromRegistry.id, company: fromRegistry };
  }

  // JWT home (thường là tập đoàn) — không dùng getActiveCompanyCode() (có thể là FM01)
  const home = (getAuthUser()?.companyCode || '').trim().toUpperCase();
  const fromHome = home ? byCode(home) : null;
  if (fromHome) {
    return { code: fromHome.code ?? fromHome.id, company: fromHome };
  }

  // Active = FM01 → thử parent FM nếu có trong list
  const active = (getActiveCompanyCode() || '').trim().toUpperCase();
  if (active) {
    const parentGuess = active.replace(/\d+$/, '');
    if (parentGuess && parentGuess !== active) {
      const parent = byCode(parentGuess);
      if (parent) {
        return { code: parent.code ?? parent.id, company: parent };
      }
    }
  }

  // Cuối cùng: FM synthetic nếu list chưa có (vẫn ghi mã tập đoàn)
  return {
    code: preferred || 'FM',
    company: preferred
      ? { id: preferred, code: preferred, name: preferred }
      : null,
  };
}
