import { useEffect } from 'react';
import { NAV_SET_TITLE } from '@linm-soft-org/linm-web-common-components';

/**
 * Sub-route topbar title (`/new`, `/:id`) — `linm:nav:set-title` for shell (and standalone mock).
 * List pages rely on nav SSOT; do not call for list paths.
 */
export function useShellNavTitle(title: string | null | undefined): void {
  useEffect(() => {
    const t = title?.trim();
    if (!t) return;
    window.dispatchEvent(new CustomEvent(NAV_SET_TITLE, { detail: t }));
    return () => {
      window.dispatchEvent(new CustomEvent(NAV_SET_TITLE, { detail: '' }));
    };
  }, [title]);
}
