import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useShellNavTitle } from '../../../router/useShellNavTitle';
import {
  Button,
  FormActions,
  FormRowCol,
  FormSkeleton,
  Input,
  LabelMoney,
  MoneyInput,
  SearchInput,
  Select,
  dispatchAppToast,
  getAuthUser,
  localInputToISOWithOffset,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { companyService } from '../../../services/company/companyService';
import type { CostPlanItemDto } from '../../../services/fpc/types';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import {
  createCustomerSearchConfig,
  type CustomerLookupItem,
} from '../../../components/search/customerSearchConfig';
import {
  createExpenseItemSearchConfig,
  fetchExpenseItems,
  type ExpenseItemLookupItem,
} from '../../../components/search/costCodeSearchConfig';
import { resolvePlanVoucherDefaultBranchCode } from '../PlanVoucherPage/resolvePlanVoucherDefaultBranch';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import {
  PROCESSING_LEVEL_OPTIONS,
  statusToProcessingLevel,
} from './processingLevel';
import styles from './CostPlanPage.module.css';

const TEST_ID = 'cost-plan';
const LIST_PATH = '/tc/kh/du-kien-chi';

type EntityType = 'ma-chi-phi' | 'doi-tuong';

const ENTITY_TYPE_OPTIONS: { value: EntityType; label: string }[] = [
  { value: 'ma-chi-phi', label: 'Mã chi phí' },
  { value: 'doi-tuong', label: 'Đối tượng' },
];

const HEADER_COLS = {
  large: [4] as number[],
  medium: [2, 2] as number[],
  small: [1, 1, 1, 1] as number[],
};

interface DailyPlanLine {
  id: string;
  entityCode: string;
  entityName: string;
  amount: number;
  note: string;
  planItemId?: string;
}

const RequiredMark: React.FC = () => (
  <span className={styles.requiredMark} aria-hidden="true">*</span>
);

function todayLocalYmd(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function formatDisplayDate(ymd: string): string {
  const [y, m, d] = ymd.split('-');
  if (!y || !m || !d) return ymd;
  return `${d}/${m}/${y}`;
}

function ymdParts(ymd: string): { year: number; month: number } {
  const [y, m] = ymd.split('-').map(Number);
  return { year: y || new Date().getFullYear(), month: m || 1 };
}

function toYmd(iso?: string | null): string {
  if (!iso) return todayLocalYmd();
  return iso.slice(0, 10);
}

function newLineId(): string {
  return `line-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

function emptyLine(): DailyPlanLine {
  return {
    id: newLineId(),
    entityCode: '',
    entityName: '',
    amount: 0,
    note: '',
  };
}

function mapPlansToLines(items: CostPlanItemDto[], planDate: string): DailyPlanLine[] {
  const dayItems = items.filter(it => {
    if (!it.effectiveFrom) return false;
    const type = (it.planScheduleType || '').toLowerCase();
    return type === 'once' && it.effectiveFrom.slice(0, 10) === planDate;
  });
  const source = dayItems.length > 0 ? dayItems : items;
  if (source.length === 0) return [emptyLine()];
  return source.map(it => ({
    id: it.id || newLineId(),
    entityCode: it.costCode,
    entityName: it.costCodeName || it.costCode,
    amount: it.plannedAmount || 0,
    note: it.note || '',
    planItemId: it.id,
  }));
}

function entityColumnTitle(entityType: EntityType): string {
  return entityType === 'doi-tuong' ? 'Đối tượng' : 'Khoản chi';
}

function entityLookupPlaceholder(entityType: EntityType): string {
  return entityType === 'doi-tuong' ? 'Đối tượng...' : 'Mã CP...';
}

const CostPlanPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { canViewPlanVoucher, canManagePlanVoucher } = useFpcPermissions();

  const isCreate = !id || id === 'new';
  const [editMode, setEditMode] = useState(isCreate);
  const [voucherId, setVoucherId] = useState<string | null>(isCreate ? null : id);
  const [headerExpanded, setHeaderExpanded] = useState(true);

  const [planDate, setPlanDate] = useState(todayLocalYmd());
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);
  const [description, setDescription] = useState('Dự kiến chi trong ngày');
  const [entityType, setEntityType] = useState<EntityType>('ma-chi-phi');
  const [lines, setLines] = useState<DailyPlanLine[]>([emptyLine()]);
  const [expenseItems, setExpenseItems] = useState<ExpenseItemLookupItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [saving, setSaving] = useState(false);
  const [voucherCode, setVoucherCode] = useState<string | null>(null);
  const [voucherStatus, setVoucherStatus] = useState('Draft');
  const [processingLevel, setProcessingLevel] = useState('1');

  const shellTitle = isCreate
    ? 'Tạo dự kiến chi theo ngày'
    : (voucherCode ? `Phiếu ${voucherCode}` : 'Dự kiến chi theo ngày');
  useShellNavTitle(shellTitle);

  /** Snapshot for Hủy */
  const [snap, setSnap] = useState<{
    planDate: string;
    branchCode: string;
    description: string;
    entityType: EntityType;
    lines: DailyPlanLine[];
    processingLevel: string;
  } | null>(null);

  const authUser = getAuthUser() as { fullName?: string; userName?: string; email?: string } | null;
  const authName = authUser?.fullName || authUser?.userName || authUser?.email || '—';
  const readOnly = !editMode || !canManagePlanVoucher;

  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);
  const customerSearchConfig = useMemo(() => createCustomerSearchConfig(), []);
  const expenseSearchConfig = useMemo(
    () => createExpenseItemSearchConfig(expenseItems),
    [expenseItems],
  );

  const lineLookupClassName = [
    styles.embeddedSearch,
    styles.lookupCodeMax150,
    styles.lookupDualInline,
  ].join(' ');
  const headerLookupClassName = lineLookupClassName;

  const loadLinesForDay = useCallback(async (date: string, branch: string) => {
    if (!branch) {
      setLines([emptyLine()]);
      return;
    }
    const { year, month } = ymdParts(date);
    const items = await fpcService.getCostPlanList({
      year,
      month,
      branchCode: branch,
    });
    setLines(mapPlansToLines(items, date));
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void (async () => {
        setLoading(true);
        setLoadError(false);
        try {
          const [companies, expenses] = await Promise.all([
            companyService.getActiveList(),
            fetchExpenseItems(),
          ]);
          setExpenseItems(expenses);

          if (!isCreate && id) {
            const voucher = await fpcService.getPlanVoucherById(id);
            const day = toYmd(voucher.effectiveFrom);
            const branch = voucher.branchCode || '';
            setVoucherId(voucher.id);
            setVoucherCode(voucher.code);
            setVoucherStatus(voucher.status || 'Draft');
            const level = statusToProcessingLevel(voucher.status);
            setProcessingLevel(level);
            setPlanDate(day);
            setBranchCode(branch);
            setDescription(voucher.description || 'Dự kiến chi trong ngày');
            const company = companies.find(c => (c.code ?? c.id) === branch) ?? null;
            setSelectedCompany(company);
            setEditMode(false);
            await loadLinesForDay(day, branch);
          } else {
            const def = await resolvePlanVoucherDefaultBranchCode(companies);
            setBranchCode(def.code);
            setSelectedCompany(def.company);
            setEditMode(true);
            setProcessingLevel('1');
            setVoucherStatus('Draft');
            setLines([emptyLine()]);
          }
        } catch {
          setLoadError(true);
          dispatchAppToast(dispatch, {
            message: 'Không thể tải phiếu dự kiến chi',
            type: 'error',
          });
        } finally {
          setLoading(false);
        }
      })();
    }, 0);
    return () => window.clearTimeout(t);
  }, [dispatch, id, isCreate, loadLinesForDay]);

  const handleEditStart = useCallback(() => {
    setSnap({
      planDate,
      branchCode,
      description,
      entityType,
      lines: lines.map(l => ({ ...l })),
      processingLevel,
    });
    setEditMode(true);
  }, [branchCode, description, entityType, lines, planDate, processingLevel]);

  const handleCancel = useCallback(() => {
    if (isCreate) {
      navigate(LIST_PATH);
      return;
    }
    if (snap) {
      setPlanDate(snap.planDate);
      setBranchCode(snap.branchCode);
      setDescription(snap.description);
      setEntityType(snap.entityType);
      setLines(snap.lines);
      setProcessingLevel(snap.processingLevel);
    }
    setEditMode(false);
  }, [isCreate, navigate, snap]);

  const handleEntityTypeChange = useCallback((next: EntityType) => {
    if (next === entityType || readOnly) return;
    setEntityType(next);
    setLines([emptyLine()]);
  }, [entityType, readOnly]);

  const patchLineEntity = useCallback((lineId: string, code: string, name: string) => {
    setLines(prev => prev.map(line =>
      line.id === lineId ? { ...line, entityCode: code, entityName: name } : line,
    ));
  }, []);

  const handleLineChange = useCallback((lineId: string, field: 'amount' | 'note', value: string | number) => {
    setLines(prev => prev.map(line =>
      line.id === lineId ? { ...line, [field]: value } : line,
    ));
  }, []);

  const handleAddLine = useCallback(() => {
    setLines(prev => [...prev, emptyLine()]);
  }, []);

  const handleCopyLine = useCallback(() => {
    setLines(prev => {
      if (prev.length === 0) return [emptyLine()];
      const last = prev[prev.length - 1];
      return [...prev, { ...last, id: newLineId(), planItemId: undefined }];
    });
  }, []);

  const handleRemoveLine = useCallback((lineId: string) => {
    setLines(prev => {
      const next = prev.filter(line => line.id !== lineId);
      return next.length > 0 ? next : [emptyLine()];
    });
  }, []);

  const handleBranchChange = useCallback((item: ActiveCompanyItem | null) => {
    if (readOnly) return;
    const code = item ? (item.code ?? item.id) : '';
    setSelectedCompany(item);
    setBranchCode(code);
  }, [readOnly]);

  const handleRefresh = useCallback(() => {
    if (!branchCode) return;
    setLoading(true);
    void loadLinesForDay(planDate, branchCode)
      .catch(() => {
        setLoadError(true);
        dispatchAppToast(dispatch, { message: 'Không thể tải dòng', type: 'error' });
      })
      .finally(() => setLoading(false));
  }, [branchCode, dispatch, loadLinesForDay, planDate]);

  const handleSave = useCallback(async () => {
    if (!canManagePlanVoucher) {
      dispatchAppToast(dispatch, { message: 'Không có quyền lưu dự kiến chi', type: 'error' });
      return;
    }
    if (!branchCode.trim()) {
      dispatchAppToast(dispatch, { message: 'Chọn chi nhánh', type: 'error' });
      return;
    }
    if (!planDate) {
      dispatchAppToast(dispatch, { message: 'Chọn ngày dự kiến', type: 'error' });
      return;
    }

    const validLines = lines.filter(l => l.entityCode.trim() && l.amount > 0);
    if (validLines.length === 0) {
      dispatchAppToast(dispatch, {
        message: 'Nhập ít nhất một dòng có mã và số tiền > 0',
        type: 'error',
      });
      return;
    }

    setSaving(true);
    try {
      const { year, month } = ymdParts(planDate);
      const dayIso = localInputToISOWithOffset(planDate);
      let activeId = voucherId;
      let codeLabel = voucherCode || '';

      if (!activeId) {
        const created = await fpcService.createPlanVoucher({
          voucherDate: dayIso,
          effectiveFrom: dayIso,
          effectiveTo: dayIso,
          planScheduleType: 'Once',
          scheduleValue: null,
          planYear: year,
          planMonth: month,
          branchCode: branchCode.trim(),
          description: description.trim() || `Dự kiến chi ${formatDisplayDate(planDate)}`,
        });
        activeId = created.id;
        codeLabel = created.code;
        setVoucherId(created.id);
        setVoucherCode(created.code);
        setVoucherStatus(created.status || 'Draft');
      } else {
        const updated = await fpcService.updatePlanVoucher(activeId, {
          voucherDate: dayIso,
          effectiveFrom: dayIso,
          effectiveTo: dayIso,
          planScheduleType: 'Once',
          scheduleValue: null,
          description: description.trim() || `Dự kiến chi ${formatDisplayDate(planDate)}`,
        });
        codeLabel = updated.code;
        setVoucherCode(updated.code);
        setVoucherStatus(updated.status || voucherStatus);
      }

      await fpcService.batchUpsertCostPlans({
        year,
        month,
        branchCode: branchCode.trim(),
        lines: validLines.map(l => ({
          costCode: l.entityCode.trim(),
          plannedAmount: l.amount,
          mustPay: l.amount,
          note: l.note || undefined,
          useCustomSchedule: true,
          effectiveFrom: dayIso,
          effectiveTo: dayIso,
          planScheduleType: 'Once',
          scheduleValue: null,
        })),
      });

      try {
        const exp = await fpcService.expandPlanVoucher(activeId);
        dispatchAppToast(dispatch, {
          message: `Đã lưu ${codeLabel} · ${exp.linesCreated} dòng lịch`,
          type: 'success',
        });
      } catch {
        dispatchAppToast(dispatch, {
          message: `Đã lưu ${codeLabel}`,
          type: 'success',
        });
      }

      setEditMode(false);
      setSnap(null);
      if (isCreate && activeId) {
        navigate(`${LIST_PATH}/${activeId}`, { replace: true });
      } else {
        await loadLinesForDay(planDate, branchCode);
      }
    } catch {
      dispatchAppToast(dispatch, {
        message: 'Lưu dự kiến chi thất bại',
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  }, [
    branchCode,
    canManagePlanVoucher,
    description,
    dispatch,
    isCreate,
    lines,
    loadLinesForDay,
    navigate,
    planDate,
    voucherCode,
    voucherId,
    voucherStatus,
  ]);

  const handlePrint = useCallback(() => {
    const el = document.getElementById('cost-plan-content');
    if (!el) return;
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write([
      '<html><head><title>Phiếu dự kiến chi theo ngày</title><meta charset="utf-8"><style>',
      'body{font-family:Arial,sans-serif;padding:20px;color:#1e293b}',
      'table{width:100%;border-collapse:collapse;margin:16px 0;font-size:12px}',
      'th,td{padding:8px 12px;border:1px solid #e2e8f0;text-align:left}',
      'th{background:#f8fafc;font-weight:600;font-size:11px;text-transform:uppercase}',
      'h1{font-size:22px;color:#059669;margin:0 0 4px}',
      '</style></head><body>',
      '<h1>Phiếu dự kiến chi theo ngày</h1>',
      `<p>Ngày in: ${new Date().toLocaleString('vi-VN')}</p>`,
      el.innerHTML,
      '</body></html>',
    ].join('\n'));
    win.document.close();
    win.print();
  }, []);

  const totalAmount = lines.reduce((s, l) => s + (Number(l.amount) || 0), 0);
  const activeCount = lines.filter(l => l.amount > 0 && l.entityCode).length;
  const dateLabel = formatDisplayDate(planDate);

  if (!canViewPlanVoucher) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-denied`}>
        <div className={styles.pageFormScroll}>Không có quyền xem dự kiến chi</div>
      </div>
    );
  }

  return (
    <div className={styles.page} data-form-page data-voucher-form-shell data-testid={`${TEST_ID}-page`}>
      {/* Z1 — Toolbar header */}
      <div className={styles.pageFormHeader}>
        <div className={styles.stickyTop}>
          <div className={styles.pageHeader}>
            <div className={styles.toolbarRow}>
              <button className={styles.backBtn} onClick={() => navigate(LIST_PATH)} type="button">
                <i className="fas fa-arrow-left" aria-hidden /> Quay lại
              </button>
              <FormActions align="end">
                {editMode ? (
                  <>
                    <Button onClick={handleCancel} data-testid={`${TEST_ID}-cancel-btn`}>
                      <i className="fas fa-times" /> Hủy
                    </Button>
                    <Button variant="primary" onClick={handleSave} disabled={saving} data-testid={`${TEST_ID}-save-btn`}>
                      <i className={`fas ${saving ? 'fa-spinner fa-spin' : 'fa-save'}`} />
                      {saving ? ' Đang lưu...' : ' Lưu'}
                    </Button>
                  </>
                ) : (
                  <>
                    {canManagePlanVoucher && (
                      <Button variant="primary" onClick={handleEditStart} data-testid={`${TEST_ID}-edit-btn`}>
                        <i className="fas fa-edit" /> Sửa
                      </Button>
                    )}
                    <Button onClick={handlePrint} data-testid={`${TEST_ID}-print-btn`}>
                      <i className="fas fa-print" /> In
                    </Button>
                    <Button onClick={handleRefresh} data-testid={`${TEST_ID}-refresh-btn`}>
                      <i className="fas fa-redo" /> Làm mới
                    </Button>
                  </>
                )}
              </FormActions>
            </div>
            <h1 className={styles.title}>
              {isCreate ? 'Tạo dự kiến chi theo ngày' : (voucherCode ? `Phiếu ${voucherCode}` : 'Dự kiến chi theo ngày')}
            </h1>
            {!isCreate && !editMode && (
              <div className={styles.viewModeHint} data-testid={`${TEST_ID}-view-hint`}>
                <i className="fas fa-eye" /> Chế độ xem — nhấn <strong>Sửa</strong> để chỉnh sửa
              </div>
            )}
            {editMode && (
              <div className={styles.readOnlyHint} data-testid={`${TEST_ID}-edit-hint`}>
                <i className="fas fa-pen" /> Đang {isCreate ? 'tạo mới' : 'chỉnh sửa'} — Lưu hoặc Hủy
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Z2 — Scroll */}
      <div
        className={`${styles.pageFormScroll}${!editMode ? ` ${styles.viewDisabled}` : ''}`}
        id="cost-plan-content"
      >
        {loading && (
          <FormSkeleton headerRows={2} lineRows={3} data-testid={`${TEST_ID}-form-skeleton`} />
        )}

        {!loading && loadError && (
          <div className={styles.section} data-testid={`${TEST_ID}-error`}>
            Không tải được dữ liệu — thử Làm mới
          </div>
        )}

        {!loading && !loadError && (
          <>
            {/* Z2b — Header CT */}
            <div className={styles.section} data-testid={`${TEST_ID}-section-header`}>
              <div className={styles.sectionTitleRow}>
                <h2 className={styles.sectionTitle}>THÔNG TIN CHỨNG TỪ</h2>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <span className={styles.sectionBadge}>{dateLabel}</span>
                  <button
                    type="button"
                    className={styles.headerToggleBtn}
                    data-testid={`${TEST_ID}-header-${headerExpanded ? 'collapse' : 'expand'}`}
                    aria-expanded={headerExpanded}
                    onClick={() => setHeaderExpanded(v => !v)}
                  >
                    <span className={styles.headerToggleIcon} aria-hidden>
                      <i className={headerExpanded ? 'fas fa-chevron-up' : 'fas fa-chevron-down'} />
                    </span>
                    {headerExpanded ? 'Thu gọn' : 'Mở rộng'}
                  </button>
                </div>
              </div>

              <FormRowCol cols={4} rowsBySize={HEADER_COLS} data-testid={`${TEST_ID}-header-labels`}>
                <FormRowCol.Item>
                  <label className={styles.label}>Ngày dự kiến<RequiredMark /></label>
                </FormRowCol.Item>
                <FormRowCol.Item>
                  <label className={styles.label}>Loại<RequiredMark /></label>
                </FormRowCol.Item>
                <FormRowCol.Item hidden={!headerExpanded}>
                  <label className={styles.label}>Người lập</label>
                </FormRowCol.Item>
                <FormRowCol.Item>
                  <label className={styles.label}>Số phiếu</label>
                </FormRowCol.Item>
              </FormRowCol>

              <FormRowCol cols={4} rowsBySize={HEADER_COLS} data-testid={`${TEST_ID}-header-inputs`}>
                <FormRowCol.Item variant="field">
                  <Input
                    type="date"
                    value={planDate}
                    onChange={e => setPlanDate(e.target.value)}
                    readOnly={readOnly}
                    data-testid={`${TEST_ID}-date`}
                  />
                </FormRowCol.Item>
                <FormRowCol.Item variant="field">
                  <Select
                    value={entityType}
                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) =>
                      handleEntityTypeChange(e.target.value as EntityType)
                    }
                    options={ENTITY_TYPE_OPTIONS}
                    disabled={readOnly}
                    data-testid={`${TEST_ID}-entity-type`}
                  />
                </FormRowCol.Item>
                <FormRowCol.Item variant="field" hidden={!headerExpanded}>
                  <Input value={authName} readOnly data-testid={`${TEST_ID}-creator`} />
                </FormRowCol.Item>
                <FormRowCol.Item variant="field">
                  <Input
                    value={voucherCode || ''}
                    placeholder="PKH-YYYYMMDD-NNNN"
                    readOnly
                    data-testid={`${TEST_ID}-code`}
                  />
                </FormRowCol.Item>
              </FormRowCol>

              <div className={styles.mixedRow} data-testid={`${TEST_ID}-header-branch-desc`}>
                <div className={styles.mixedItem}>
                  <label className={styles.label}>Chi nhánh / Đơn vị<RequiredMark /></label>
                  <SearchInput
                    config={companySearchConfig}
                    className={headerLookupClassName}
                    value={branchCode}
                    primaryDisplay={selectedCompany?.code ?? branchCode}
                    secondaryDisplay={selectedCompany?.name ?? ''}
                    onChange={item => handleBranchChange(item as ActiveCompanyItem)}
                    onClear={() => handleBranchChange(null)}
                    showLabel={false}
                    showSecondaryInput
                    placeholder="Chi nhánh..."
                    disabled={readOnly}
                    data-testid={`${TEST_ID}-branch`}
                  />
                </div>
                {headerExpanded && (
                  <div className={styles.mixedItem}>
                    <label className={styles.label}>Diễn giải</label>
                    <Input
                      value={description}
                      onChange={e => setDescription(e.target.value)}
                      placeholder="Nhập diễn giải"
                      readOnly={readOnly}
                      data-testid={`${TEST_ID}-desc`}
                    />
                  </div>
                )}
              </div>
            </div>

            {/* Z2d — Lines */}
            <div className={styles.section} data-testid={`${TEST_ID}-section-lines`}>
              <div className={styles.sectionTitleRow}>
                <h2 className={styles.sectionTitle}>CHI TIẾT DỰ KIẾN CHI</h2>
              </div>

              <div className={styles.tableWrapper}>
                <table className={styles.linesTable}>
                  <thead>
                    <tr>
                      <th style={{ width: 48 }}>STT</th>
                      <th className={styles.thEntityLookup}>{entityColumnTitle(entityType)}</th>
                      <th style={{ width: 160 }}>Dự kiến chi</th>
                      <th>Ghi chú</th>
                      <th style={{ width: 40 }} />
                    </tr>
                  </thead>
                  <tbody>
                    {lines.map((line, idx) => (
                      <tr key={line.id} className={styles.lineRow} data-testid={`${TEST_ID}-line-${idx}`}>
                        <td style={{ textAlign: 'center', color: '#94a3b8', fontWeight: 500 }}>{idx + 1}</td>
                        <td className={styles.tdEntityLookup}>
                          {readOnly ? (
                            line.entityCode ? (
                              <span className={styles.entityViewDual}>
                                <span className={styles.entityViewCode}>{line.entityCode}</span>
                                <span className={styles.entityViewName}>{line.entityName || '—'}</span>
                              </span>
                            ) : (
                              <span style={{ color: '#94a3b8' }}>—</span>
                            )
                          ) : entityType === 'ma-chi-phi' ? (
                            <SearchInput
                              key={`exp-${entityType}-${line.id}`}
                              config={expenseSearchConfig}
                              className={lineLookupClassName}
                              value={line.entityCode}
                              primaryDisplay={line.entityCode}
                              secondaryDisplay={line.entityName}
                              onChange={item => {
                                const it = item as ExpenseItemLookupItem;
                                patchLineEntity(line.id, it.code, it.name);
                              }}
                              onClear={() => patchLineEntity(line.id, '', '')}
                              showLabel={false}
                              showSecondaryInput
                              placeholder={entityLookupPlaceholder(entityType)}
                              data-testid={`${TEST_ID}-line-${idx}-entity`}
                            />
                          ) : (
                            <SearchInput
                              key={`cus-${entityType}-${line.id}`}
                              config={customerSearchConfig}
                              className={lineLookupClassName}
                              value={line.entityCode}
                              primaryDisplay={line.entityCode}
                              secondaryDisplay={line.entityName}
                              onChange={item => {
                                const it = item as CustomerLookupItem;
                                patchLineEntity(line.id, it.code, it.name);
                              }}
                              onClear={() => patchLineEntity(line.id, '', '')}
                              showLabel={false}
                              showSecondaryInput
                              placeholder={entityLookupPlaceholder(entityType)}
                              data-testid={`${TEST_ID}-line-${idx}-entity`}
                            />
                          )}
                        </td>
                        <td className={styles.tdAmount}>
                          {readOnly ? (
                            <span className={styles.colAmount}>{line.amount.toLocaleString('vi-VN')}</span>
                          ) : (
                            <MoneyInput
                              className={styles.lineInput}
                              value={line.amount}
                              onChange={v => handleLineChange(line.id, 'amount', v)}
                              data-testid={`${TEST_ID}-line-${idx}-amount`}
                            />
                          )}
                        </td>
                        <td>
                          <Input
                            className={`${styles.lineInput} ${styles.lineInputNote}`}
                            value={line.note}
                            onChange={e => handleLineChange(line.id, 'note', e.target.value)}
                            placeholder="Nhập ghi chú..."
                            readOnly={readOnly}
                            data-testid={`${TEST_ID}-line-${idx}-note`}
                          />
                        </td>
                        <td className={styles.tdDel}>
                          {!readOnly && (
                            <button
                              type="button"
                              className={styles.btnDeleteLine}
                              onClick={() => handleRemoveLine(line.id)}
                              title="Xóa dòng"
                              data-testid={`${TEST_ID}-line-${idx}-delete`}
                            >
                              <i className="fas fa-trash-alt" />
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {!readOnly && (
                <div className={styles.linesActions}>
                  <button
                    type="button"
                    className={styles.btnAddLine}
                    onClick={handleAddLine}
                    data-testid={`${TEST_ID}-add-line`}
                  >
                    <i className="fas fa-plus" style={{ marginRight: 6 }} />
                    Thêm dòng
                  </button>
                  <button
                    type="button"
                    className={styles.btnCopyLine}
                    onClick={handleCopyLine}
                    disabled={lines.length === 0}
                    data-testid={`${TEST_ID}-copy-line`}
                  >
                    <i className="fas fa-copy" style={{ marginRight: 6 }} />
                    Sao chép dòng
                  </button>
                </div>
              )}
            </div>
          </>
        )}
      </div>

      {/* Z3 — Footer pin */}
      {!loading && (
        <div className={styles.pageFormFooter}>
          <div className={styles.footer}>
            <div className={styles.footerLeft}>
              <label className={styles.footerLabel}>Mức xử lý</label>
              <Select
                className={styles.footerSelect}
                value={processingLevel}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setProcessingLevel(e.target.value)}
                options={[...PROCESSING_LEVEL_OPTIONS]}
                disabled={readOnly}
                data-testid={`${TEST_ID}-processingLevel`}
              />
              <span
                className={styles.footerTypeLabel}
                style={{
                  color: '#92400e',
                  fontWeight: 600,
                  fontSize: 14,
                  padding: '4px 10px',
                  borderRadius: 4,
                  background: '#fef3c7',
                }}
              >
                Dự kiến chi
              </span>
              <span style={{ fontSize: 13, color: '#64748b' }}>
                {editMode ? `Đang chỉnh sửa · ${activeCount} dòng` : `${activeCount} dòng`}
              </span>
            </div>
            <div className={styles.totalBlock}>
              <LabelMoney
                label="Tổng dự kiến chi:"
                value={totalAmount}
                variant="footer"
                emphasize
                data-testid={`${TEST_ID}-footer-total`}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CostPlanPage;
