import { getPermissionsCacheEntry } from '@linm-soft-org/linm-web-common-components';
import { isPermissionsLocalModeActive } from '../dev/isPermissionsLocalMode';

export function readCachedPermissionCodes(): string[] {
  const payload = getPermissionsCacheEntry()?.payload;
  const codes = payload?.permissionCodes;
  if (!Array.isArray(codes)) return [];
  return codes.filter((c): c is string => typeof c === 'string' && c.length > 0);
}

export function hasPermissionCode(code: string): boolean {
  if (isPermissionsLocalModeActive()) return true;
  const target = code.trim();
  if (!target) return false;
  return readCachedPermissionCodes().some(
    c => c.localeCompare(target, undefined, { sensitivity: 'accent' }) === 0,
  );
}

const FPC_PREFIX = 'erp-kpi';

/** FPC (Financial Planning & Control) page-level permissions. */
export function useFpcPermissions() {
  return {
    canViewCeoDashboard: hasPermissionCode(`${FPC_PREFIX}:ceo-dashboard:read`),
    canViewDailyCash: hasPermissionCode(`${FPC_PREFIX}:daily-cash:read`),
    canManageDailyCash: hasPermissionCode(`${FPC_PREFIX}:daily-cash:write`),
    canApproveDailyCash: hasPermissionCode(`${FPC_PREFIX}:daily-cash:approve`),
    canDeleteDailyCash: hasPermissionCode(`${FPC_PREFIX}:daily-cash:delete`),
    canViewPlanVersions: hasPermissionCode(`${FPC_PREFIX}:plan-versions:read`),
    canManagePlanVersions: hasPermissionCode(`${FPC_PREFIX}:plan-versions:write`),
    canDeletePlanVersions: hasPermissionCode(`${FPC_PREFIX}:plan-versions:delete`),
    canViewCategories: hasPermissionCode(`${FPC_PREFIX}:categories:read`),
    canManageCategories: hasPermissionCode(`${FPC_PREFIX}:categories:write`),
    canViewAlerts: hasPermissionCode(`${FPC_PREFIX}:alerts:read`),
    canConfigureAlerts: hasPermissionCode(`${FPC_PREFIX}:alerts:configure`),
    canView13Week: hasPermissionCode(`${FPC_PREFIX}:13-week:read`),
    canViewPlanVsActual: hasPermissionCode(`${FPC_PREFIX}:plan-vs-actual:read`),
    canViewBranchPnl: hasPermissionCode(`${FPC_PREFIX}:branch-pnl:read`),
    canViewConsolidatedPnl: hasPermissionCode(`${FPC_PREFIX}:consolidated-pnl:read`),
    canViewProjectedBs: hasPermissionCode(`${FPC_PREFIX}:projected-bs:read`),
    canViewScenarios: hasPermissionCode(`${FPC_PREFIX}:scenarios:read`),
    canManageScenarios: hasPermissionCode(`${FPC_PREFIX}:scenarios:write`),
    canViewExpansionSimulator: hasPermissionCode(`${FPC_PREFIX}:expansion-simulator:read`),
    canRunExpansionSimulator: hasPermissionCode(`${FPC_PREFIX}:expansion-simulator:write`),
    canViewExpansionFormula: hasPermissionCode(`${FPC_PREFIX}:expansion-formula:read`)
      || hasPermissionCode(`${FPC_PREFIX}:expansion-simulator:read`),
    canManageExpansionFormula: hasPermissionCode(`${FPC_PREFIX}:expansion-formula:write`)
      || hasPermissionCode(`${FPC_PREFIX}:expansion-simulator:write`),
    canDeleteExpansionFormula: hasPermissionCode(`${FPC_PREFIX}:expansion-formula:delete`)
      || hasPermissionCode(`${FPC_PREFIX}:expansion-simulator:write`),
    canViewPlanVoucher: hasPermissionCode(`${FPC_PREFIX}:plan-voucher:read`),
    canManagePlanVoucher: hasPermissionCode(`${FPC_PREFIX}:plan-voucher:write`),
    canDeletePlanVoucher: hasPermissionCode(`${FPC_PREFIX}:plan-voucher:delete`),
    canViewPriorityClass: hasPermissionCode(`${FPC_PREFIX}:priority-class:read`),
    canManagePriorityClass: hasPermissionCode(`${FPC_PREFIX}:priority-class:write`),
    canDeletePriorityClass: hasPermissionCode(`${FPC_PREFIX}:priority-class:delete`),
    canViewSensitivityVariable: hasPermissionCode(`${FPC_PREFIX}:sensitivity-variable:read`),
    canManageSensitivityVariable: hasPermissionCode(`${FPC_PREFIX}:sensitivity-variable:write`),
    canDeleteSensitivityVariable: hasPermissionCode(`${FPC_PREFIX}:sensitivity-variable:delete`),
    canExportReports: hasPermissionCode(`${FPC_PREFIX}:export`),
  };
}
